"
BEGIN { FS=OFS="\t" }
NR==1 {
  n=NF-1
  for (j=2; j<=NF; j++) {
    h[j]=$j
    gsub(/[ -]/, "_", h[j])
  }
  next
}
{
  r++
  gene[r]=$1
  for (j=2; j<=NF; j++) {
    v=$j+0
    x[r,j]=v
    total[j]+=v
  }
}
END {
  for (j=2; j<=n+1; j++) a[j-1]=total[j]
  for (i=2; i<=n; i++) {
    z=a[i]; k=i-1
    while (k>=1 && a[k]>z) { a[k+1]=a[k]; k-- }
    a[k+1]=z
  }
  if (n%2) M=a[(n+1)/2]; else M=(a[n/2]+a[n/2+1])/2
  rawS=10+0.7*(n-10)
  S=int(rawS)
  if (S<rawS) S++
  cpm_cut=10/M*1000000

  kept=0
  for (i=1; i<=r; i++) {
    sum=0; present=0
    for (j=2; j<=n+1; j++) {
      sum+=x[i,j]
      cpm=x[i,j]/total[j]*1000000
      if (cpm>=cpm_cut) present++
    }
    if (present>=S && sum>=1000) kept++
  }
  printf "N\t%d\nM\t%.10g\nS\t%d\nCPM_cutoff\t%.10g\ninput_genes\t%d\nretained_genes\t%d\n", n, M, S, cpm_cut, r, kept
}
"
